import{_ as r,o as t,c as a,ah as s}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"12. März: Der Zeuge, der zurückbiss – Mattura vs. Hanger im U-Ausschuss","description":"Christian Mattura liefert sich im Pilnacek-U-Ausschuss ein heftiges Match mit der ÖVP. Ein Fest für jeden Drehbuchautor.","frontmatter":{"title":"12. März: Der Zeuge, der zurückbiss – Mattura vs. Hanger im U-Ausschuss","description":"Christian Mattura liefert sich im Pilnacek-U-Ausschuss ein heftiges Match mit der ÖVP. Ein Fest für jeden Drehbuchautor.","date":"2026-03-12T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-03-12-mattura-u-ausschuss-match.md","filePath":"logbuch/2026-03-12-mattura-u-ausschuss-match.md"}'),n={name:"logbuch/2026-03-12-mattura-u-ausschuss-match.md"};function i(u,e,h,d,o,g){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="⚖️-12-marz-der-zeuge-der-zuruckbiss-–-mattura-vs-hanger-im-u-ausschuss" tabindex="-1">⚖️ 12. März: Der Zeuge, der zurückbiss – Mattura vs. Hanger im U-Ausschuss <a class="header-anchor" href="#⚖️-12-marz-der-zeuge-der-zuruckbiss-–-mattura-vs-hanger-im-u-ausschuss" aria-label="Permalink to &quot;⚖️ 12. März: Der Zeuge, der zurückbiss – Mattura vs. Hanger im U-Ausschuss&quot;">​</a></h1><p>Während unser Projekt auf Reddit viral geht, lieferte die Realität im <strong>Pilnacek-Untersuchungsausschuss</strong> heute (12. März 2026) Stoff, den man sich für eine Mockumentary kaum besser ausdenken könnte.</p><h3 id="das-duell-christian-mattura-vs-andreas-hanger" tabindex="-1"><strong>Das Duell: Christian Mattura vs. Andreas Hanger</strong> <a class="header-anchor" href="#das-duell-christian-mattura-vs-andreas-hanger" aria-label="Permalink to &quot;**Das Duell: Christian Mattura vs. Andreas Hanger**&quot;">​</a></h3><p>Im Zentrum stand <strong>Christian Mattura</strong>, jener Unternehmer, der das mittlerweile legendäre „Pilnacek-Tape“ heimlich aufgenommen hatte. Doch wer einen defensiven Zeugen erwartete, wurde enttäuscht. Mattura ging sofort in den Angriffsmodus über.</p><ul><li><strong>Der Frontalangriff:</strong> Bereits im Eingangsstatement warf Mattura dem ÖVP-Fraktionsführer <strong>Andreas Hanger</strong> ein „befremdliches Demokratieverständnis“ vor. Er beschuldigte die ÖVP, Zeugen gezielt zu diskreditieren, um von den eigenen Skandalen abzulenken.</li><li><strong>Die „Hanger-Skala“:</strong> Die Stimmung war so giftig, dass SPÖ-Abgeordneter Kai Jan Krainer trocken anmerkte, Hangers Fragen lägen auf einer „10-teiligen Hanger-Skala ganz unten“.</li><li><strong>„Ist das eine Drohung?“:</strong> Als Hanger versuchte, Matturas Hintergrund im Glücksspielsektor gegen ihn zu verwenden, konterte dieser kühl mit der Frage: „Ist das eine Drohung?“. Ein Moment, der perfekt die Atmosphäre im Ausschuss widerspiegelt.</li></ul><h3 id="neue-details-zum-„verschwundenen-laptop" tabindex="-1"><strong>Neue Details zum „Verschwundenen Laptop“</strong> <a class="header-anchor" href="#neue-details-zum-„verschwundenen-laptop" aria-label="Permalink to &quot;**Neue Details zum „Verschwundenen Laptop“**&quot;">​</a></h3><p>Mattura brachte zudem brisante neue Gerüchte ins Spiel. Er behauptete, von einer Vertrauten gehört zu haben, dass Bundespolizeidirektor Michael Takacs gesagt haben soll, der Laptop von Pilnacek müsse <strong>„verschwinden“</strong>. Zudem war von mysteriösen Geldsummen aus Dubai die Rede.</p><h3 id="bedeutung-fur-das-„horten-mysterium" tabindex="-1"><strong>Bedeutung für das „Horten-Mysterium“</strong> <a class="header-anchor" href="#bedeutung-fur-das-„horten-mysterium" aria-label="Permalink to &quot;**Bedeutung für das „Horten-Mysterium“**&quot;">​</a></h3><p>Dieser Tag im U-Ausschuss ist für uns <strong>Content-Gold</strong>:</p><ol><li><strong>Charakter-Studie:</strong> Mattura ist der Prototyp des „unbequemen Zeugen“, den wir in Teil 4 brauchen.</li><li><strong>Die Ästhetik des Interrogativs:</strong> Die Art und Weise, wie Fragen als Waffen eingesetzt werden (Stichwort Hanger), wird ein zentrales Stilmittel unserer Gerichtsszenen.</li><li><strong>Das Tape-Motiv:</strong> Heimliche Aufnahmen sind das ultimative Werkzeug gegen das „Archiv des Schweigens“.</li></ol><hr><p><strong>„In einem System, das auf Schweigen basiert, ist das heimliche Mikrofon der einzige Lautsprecher der Wahrheit.“</strong></p><p>👉 <a href="/recherche/christian-mattura-pilnacek-tape.html">Mehr zum Pilnacek-Tape und Christian Mattura</a> 👉 <a href="/logbuch/">Zurück zum Logbuch-Index</a></p><hr><p><em>Berichterstattung vom 12. März 2026. Die Realität schreibt das beste Drehbuch.</em></p>',15)])])}const m=r(n,[["render",i]]);export{c as __pageData,m as default};
